def is_palindrome(number: int) -> bool:
    """ Given a positive integer number, determine if its digits are a
    palindrome, without converting the number into a string.
    >>> is_palindrome(123)
    False
    >>> is_palindrome(2468642)
    True
    """
    return str(number) == str(number)[::-1]


