def binary_gcd(a: int, b: int) -> int:
    """ Return a greatest common divisor of two integers a and b
    >>> binary_gcd(3, 5)
    1
    >>> binary_gcd(25, 15)
    5
    """
    if a == 0:
        return b
    if b == 0:
        return a
    if a % 2 == 0 and b % 2 == 0:
        return 2 * binary_gcd(a // 2, b // 2)
    if a % 2 == 0:
        return binary_gcd(a // 2, b)
    if b % 2 == 0:
        return binary_gcd(a, b // 2)
    if a > b:
        return binary_gcd((a - b) // 2, b)
