def filter_by_list(values: list, inclusion: list, skip_on_error=False):
    """ Given a list of values, filter it by another list of inclusion:
        [1,2,3,4,5,6], [0,1,0,1,0,1] => [2,4,6]
        If lists do not match in length, exception is raised
    """
    assert len(values) == len(inclusion), 'Length of inclusion should match length of values'

    results = []
    for idx, include in enumerate(inclusion):
        try:
            include = bool(include)
            if include:
                results.append(values[idx])
        except Exception as e:
            if skip_on_error:
                print('Exception occurred during filtering: ', e)
            else:
                raise e
    return results

