def all_elements_are_unique(numbers: List[int]) -> bool:
    """ Check if given list of integers consists all unique elements
    >>> all_elements_are_unique([1, 3, 5])
    True
    >>> all_elements_are_unique([3, 3, 3])
    False
    """
    return len(numbers) == len(set(numbers))


def multyply_unique_numbers(numbers: List[int]) -> int:
    """ Return product of unique elements of given list of integers
    >>> multyply_unique_numbers([2, 3, 4])
    24
    >>> multyply_unique_numbers([1, 1, 2])
    2
    """
    return 0 if len(numbers) == 0 else eval('*'.join(str(s) for s in set(numbers)))


