def dict_to_xml(d: dict, level=0):
    """Converts a dictionary to XML with nested keys"""
    if not d:
        return ""

    padding = "    " * level
    next_padding = "    " * (level + 1)
    s = padding + "<" + str(list(d.keys())[0]) + ">"
    for value in d.values():
        if type(value) == dict:
            s += "\n" + dict_to_xml(value, level + 1) + "\n" + next_padding
        else:
            s += value
    return s + "\n" + padding + "</" + str(list(d.keys())[0]) + ">"


