def encode_rail_fence_cipher(message: str, key: int):
    """
    Encodes string using Rail-fence cipher. The key is the number of rails.
    """
    rails = ["" for _ in range(key)]
    rail = 0
    direction = 1
    for ch in message:
        rails[rail] += ch
        rail += direction
        if rail == key - 1 or rail == 0:
            direction = -direction
    return "".join(rails)


def decode_rail_fence_cipher(encoded_message: str, key: int):
    """
    Decodes string encoded with Rail-fence cipher. The key is the number of rails.
    """
    rails = ["" for _ in range(key)]
    rail = 0
    direction = 1
    for i in range(len(encoded_message)):
        rails[rail] += encoded_message[i]
        rail += direction
        if rail == key - 1 or rail == 0:
            direction = -direction
    return "".join(rails)


