def search_position(element: int, sequence: Sequence[int]) -> int:
    if len(sequence) < 1:
        return -1
    first: int = 0
    last: int = len(sequence) - 1
    while first <= last:
        middle: int = (first + last) // 2
        if sequence[middle] < element:
            first = middle + 1
        elif sequence[middle] > element:
            last = middle - 1
        else:
            return middle
    return -1

