def is_harshad(n):
    """
    Short Description:
        Your team of statisticians has discovered a way to uniquely identify humans by a specific test which counts the number of perfect squares that evenly divide into the number (perfect squares include: 1, 4, 9, 16, 25, ...). Your team has given the name "Harshad" to any number that is divisible by the count of the number of perfect squares that divide into itself. 

    A harshad number is a number that is divisible by the count of the number of perfect squares that divide into itself.
    Example:
        is_harshad(8) =>  True
        is_harshad(27) => True
        is_harshad(29) => False
        is_harshad(19) => False
    """
    total_squares = 0
    for number in range(1, n + 1):
        if n % number == 0:
            if number**2 <= n:
                total_squares += 1
    return n % total_squares == 0


