    key = {'a':'c', 'e':'g', 'i':'k', 'o':'q', 'u':'w'}
    output = ''
    for c in message:
        if c in 'aeiouAEIOU':
            output += key[c.lower()].upper() if c.isupper() else key[c]
        elif c.isalpha():
            output += c.swapcase()
        else:
            output += c
    return output
