# Min Heap Implementation

# - Min Heap: A Complete Binary Tree where the value of each node is less than or equal to the value of its children
# - Root Node: The node at the top of the heap
# - Leaf Node: A node with no children
# - Parent Node: A node with at least one child
# - Child Node: A node with a parent
# - Sibling Nodes: Nodes that share the same parent
# - Depth of a Node: The number of edges from the root to the node
# - Height of a Node: The number of edges from the node to the deepest leaf
# - Height of a Tree: The height of the root node
# - Size of a Tree: The number of nodes in the tree
# - Path: A sequence of nodes and edges connecting a node with a descendant
# - Ancestor: A node reachable by tracing the path upward
# - Descendant: A node reachable by tracing the path downward
# - Leaf Nodes: Nodes with no children
# - Internal Nodes: Nodes with at least one child
# - Subtree: A tree consisting of a node and its descendants
# - Forest: A collection of trees


class MinHeap:
    """
    Min Heap Class
    """

    def __init__(self):
        self.heap = []

    def parent(self, i):
        return (i - 1) // 2

    def left_child(self, i):
        return 2 * i + 1

    def right_child(self, i):
        return 2 * i + 2

    def swap(self, i, j):
        self.heap[i], self.heap[j] = self.heap[j], self.heap[i]

    def insert(self, val):
        self.heap.append(val)
        self.heapify_up(len(self.heap) - 1)

    def heapify_up(self, i):
        while i > 0 and self.heap[i] < self.heap[self.parent(i)]:
            self.swap(i, self.parent(i))
            i = self.parent(i)

    def extract_min(self):
        if len(self.heap) == 0:
            return None
        if len(self.heap) == 1:
            return self.heap.pop()

        min_val = self.heap[0]
        self.heap[0] = self.heap.pop()
        self.heapify_down(0)

        return min_val

    def heapify_down(self, i):
        min_index = i
        left = self.left_child(i)
        right = self.right_child(i)

        if left < len(self.heap) and self.heap[left] < self.heap[min_index]:
            min_index = left
        if right < len(self.heap) and self.heap[right] < self.heap[min_index]:
            min_index = right

        if i != min_index:
            self.swap(i, min_index)
            self.heapify_down(min_index)

    def delete(self, val):
        index = -1
        for i in range(len(self.heap)):
            if self.heap[i] == val:
                index = i
                break

        if index == -1:
            return None
        else:
            self.heap[index] = self.heap.pop()
            self.heapify_up(index)
            self.heapify_down(index)

    def is_empty(self):
        return len(self.heap) == 0

    def get_size(self):
        return len(self.heap)

    def peek(self):
        if self.is_empty():
            return None
        else:
            return self.heap[0]

    def get_min(self):
        if self.is_empty():
            return None
        else:
            return self.heap[0]

    def print_heap(self):
        print(self.heap)


